const input = $json.body ?? $json;
const booleanValue = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value > 0;
  return ['true', 'yes', '1', 'required'].includes(String(value ?? '').toLowerCase());
};
const handoffRequired = booleanValue(input.handoff ?? input.handoff_required) || Boolean(input.handoff_reason);
return [{
  json: {
    event: 'call.completed',
    source: 'callflow-ai',
    session_id: input.session_id ?? input.sessionId ?? null,
    call_sid: input.call_sid ?? input.callSid ?? null,
    caller: input.caller ?? input.from ?? null,
    status: input.status ?? 'completed',
    outcome: input.outcome ?? (handoffRequired ? 'human_handoff' : 'resolved'),
    intent: input.intent ?? 'general_enquiry',
    summary: input.summary ?? '',
    turn_count: Number(input.turn_count ?? input.turns ?? 0),
    handoff_required: handoffRequired,
    handoff_reason: input.handoff_reason ?? null,
    started_at: input.started_at ?? null,
    ended_at: input.ended_at ?? new Date().toISOString(),
    duration_seconds: Number(input.duration_seconds ?? 0),
    recording_url: input.recording_url ?? null,
    received_at: new Date().toISOString()
  }
}];
